// Command side: Emitting an event
public void withdraw(UUID accountId, BigDecimal amount) {
    Account account = repository.load(accountId);
    account.withdraw(amount); // Logic validates state
    eventStore.save(new MoneyWithdrawnEvent(accountId, amount, Instant.now()));
}

// Query side: Projector updating a read model
@EventListener
public void on(MoneyWithdrawnEvent event) {
    readModelRepository.updateBalance(event.getAccountId(), -event.getAmount());
}
